  it('accepts discountPercent when adding a line', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: products[1].sku, qty: 3, discountPercent: 15 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[1].discountPercent, 15);
  });

  it('defaults to tier discount when adding a line without it', () => {
    const products = listProducts();
    const customers = listCustomers();
    const standardCustomer = customers.find((c) => c.tier === 'standard');
    const invoiceResult = createInvoice({
      customerId: standardCustomer.id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: products[1].sku, qty: 3 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[1].discountPercent, 0);
