91	/**
92	 * Calculate the VAT for a single line: (lineTotal - lineDiscount) × (vatRate / 100), rounded per line.
93	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
94	 * @returns {number}
95	 */
96	export function lineVAT(line) {
97	  const total = lineTotal(line);
98	  const discount = lineDiscount(line);
99	  const amountAfterDiscount = total - discount;
100	  const vatRate = line.vatRate ?? 0;
101	  const vat = roundCents(amountAfterDiscount * (vatRate / 100));
102	  return Math.max(0, vat);
103	}
104	
105	/**
106	 * Calculate the totals for an invoice: subtotal, discount, vat, and total.
107	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }}
108	 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
